using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class CapacityMessageHandlerProof {
 class Memory:IHorizontalRasterMemory {
  public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public void Load(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++){int p=(seg<<4)+i;byte old;if(Bytes.TryGetValue(p,out old)&&old!=b[i])throw new Exception("Physical alias mismatch");Bytes[p]=b[i];}}
  public ushort ReadWord(ushort s,ushort o){byte a,b;if(!Bytes.TryGetValue((s<<4)+o,out a)||!Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b))throw new Exception("Uncaptured word read");return (ushort)(a|b<<8);}
  public void WriteWord(ushort s,ushort o,ushort v){int p=(s<<4)+o,q=(s<<4)+(ushort)(o+1);if(!Bytes.ContainsKey(p)||!Bytes.ContainsKey(q))throw new Exception("Uncaptured word write");Bytes[p]=(byte)v;Bytes[q]=(byte)(v>>8);}
  public void OrByte(ushort s,ushort o,byte b){throw new Exception("Video effect");}
  public void Compare(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++)if(Bytes[(seg<<4)+i]!=b[i])throw new Exception("Segment "+seg.ToString("X4")+" byte "+i.ToString("X4"));}
 }
 static ushort H(string s){return Convert.ToUInt16(s,16);}static SignedDivide16State Parse(string[] a,int i){return new SignedDivide16State{AX=H(a[i]),BX=H(a[i+1]),CX=H(a[i+2]),DX=H(a[i+3]),SI=H(a[i+4]),DI=H(a[i+5]),BP=H(a[i+6]),CS=H(a[i+7]),IP=H(a[i+8]),DS=H(a[i+9]),ES=H(a[i+10]),SS=H(a[i+11]),SP=H(a[i+12]),EFlags=Convert.ToUInt32(a[i+13],16)};}
 static string Show(SignedDivide16State s){return s.AX+":"+s.BX+":"+s.CX+":"+s.DX+":"+s.SI+":"+s.DI+":"+s.BP+":"+s.CS+":"+s.IP+":"+s.DS+":"+s.ES+":"+s.SS+":"+s.SP+":"+s.EFlags;}

 static SignedDivide16State State(string d,string n){return Parse(File.ReadAllText(Path.Combine(d,n+"-state.txt")).Split((char[])null,StringSplitOptions.RemoveEmptyEntries),0);}
 static void Check(Memory m,string d,string n,SignedDivide16State s){if(Show(s)!=Show(State(d,n)))throw new Exception(n+" CPU: "+Show(s)+" expected "+Show(State(d,n)));m.Compare(s.DS,File.ReadAllBytes(Path.Combine(d,n+"-ds.bin")));m.Compare(s.SS,File.ReadAllBytes(Path.Combine(d,n+"-ss.bin")));}
 class Effects:ICapacityCallEffects{
  public string Dir;public int Count;
  public SignedDivide16State Call(CapacityCallKind kind,IHorizontalRasterMemory memory,SignedDivide16State s){string n="call-"+Count;if(kind!=(Count==0?CapacityCallKind.StringOutput:CapacityCallKind.Followup))throw new Exception("Call order");Memory m=(Memory)memory;Check(m,Dir,n+"-entry",s);SignedDivide16State after=State(Dir,n+"-returned");Memory captured=new Memory();captured.Load(after.DS,File.ReadAllBytes(Path.Combine(Dir,n+"-returned-ds.bin")));captured.Load(after.SS,File.ReadAllBytes(Path.Combine(Dir,n+"-returned-ss.bin")));foreach(var b in captured.Bytes)m.Bytes[b.Key]=b.Value;Count++;return after;}
 }
 static int Main(string[] args){try{int checks=0;for(int c=0;c<2;c++){string d=Path.Combine(args[0],"case-"+c);string[] cfg=File.ReadAllText(Path.Combine(d,"config.txt")).Split((char[])null,StringSplitOptions.RemoveEmptyEntries);for(int mode=0;mode<3;mode++){string start=mode==2?"comparison":"entry",end=mode==0?"before-return":mode==1?"returned":"outer-returned";SignedDivide16State s=State(d,start);Memory m=new Memory();m.Load(s.DS,File.ReadAllBytes(Path.Combine(d,start+"-ds.bin")));m.Load(s.SS,File.ReadAllBytes(Path.Combine(d,start+"-ss.bin")));if(mode==2){ushort seg=H(cfg[2]),count=H(cfg[3]);m.Bytes[(seg<<4)]=(byte)count;m.Bytes[(seg<<4)+1]=(byte)(count>>8);}Effects effects=new Effects{Dir=d};SignedDivide16State result;if(mode==2){var r=BufferedPointCaller.ExecuteCapacityAtComparisonThroughReturn(m,effects,s,H(cfg[4]),H(cfg[5]));if(r.Outcome!=BufferedPointOutcome.Completed||!r.RetfExecuted)throw new Exception("Caller outcome");result=r.State;}else{var r=mode==0?CapacityMessageHandler.Execute(m,effects,s,H(cfg[4]),H(cfg[5])):CapacityMessageHandler.ExecuteThroughReturn(m,effects,s,H(cfg[4]),H(cfg[5]));if(r.Outcome!=CapacityMessageOutcome.ReachedReturn||r.RetfExecuted!=(mode==1))throw new Exception("Helper outcome");result=r.State;}Check(m,d,end,result);if(effects.Count!=H(cfg[6]))throw new Exception("Call count");checks++;Console.WriteLine("PASS capacity fixture "+c+" mode "+mode+": 13 word registers, full EFLAGS, complete DS/SS views, recorded external call boundaries.");}}Console.WriteLine("PASS "+checks+" original fixture checks; callee effects replayed explicitly.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
